import type { HoverRemarkProp } from '~/ui/parts/HoverRemark'
import { ReferIntoroRemarkFrame } from '../common'


export function AssociationGameRemark(prop: HoverRemarkProp) {
  return (
    <ReferIntoroRemarkFrame {...prop}>
      <AssociationGame />
    </ReferIntoroRemarkFrame>
  )
}


export function AssociationGame() {
  return (
    <>
      まず頭を空っぽにして、でたらめにブロックを組み立てます。(なるべくやったことのないブロックや色の組み合わせ)<br/>
      それを見て、「顔の一部に見える」とか「タンスの引出しに見える」とか連想するゲーム。(LaQはブロックがシンプルなので色も発想のポイントになるかと)<br/>
      結局はLaQなので、本来まったく身の周りのモノと関係ないのですが、"形"や"色合い"、"動き"という点だけに着目して「似てる」と結びつける遊びです。<br/>
      その後、その結びつけたイメージをLaQで作っていきます。<br/>
    </>
  )
}

export function ReverseAssociationGameRemark(prop: HoverRemarkProp) {
  return (
    <ReferIntoroRemarkFrame {...prop}>
      でたらめに組み立てたLaQを見て、「顔の一部に見える」とか「タンスの引出しに見える」とか連想して、作っていくゲームを冒頭で紹介しています。<br/>
      それを繰り替えしていると、身の周りにある家具や装置を見て、「LaQならこう作れるかも〜」と逆方向に考えられるようになってくる感じ。<br/>
      そうやって「◯◯がない。じゃぁLaQで用意するか」と工作を手段として使っていけるようになります。<br/>
    </ReferIntoroRemarkFrame>
  )
}

